"although":{a:[{tr:"e. -e rağmen, her ne kadar",ex:"Although the treatment showed promise in early trials, its long-term effects remain largely unknown.",exTr:"Tedavi erken denemelerde umut vaat etmiş olsa da uzun vadeli etkileri büyük ölçüde bilinmemektedir."}],kl:[{en:"although ..., ... still",tr:"... olsa da yine de"},{en:"although not",tr:"... olmasa da"}]},
"number":{a:[{tr:"i. sayı, rakam, adet",ex:"The number of electric vehicles on the road has risen sharply in the past five years.",exTr:"Yollardaki elektrikli araç sayısı, son beş yılda keskin bir şekilde arttı."}],kl:[{en:"a number of",tr:"birçok, birtakım"},{en:"the number of",tr:"-in sayısı"},{en:"a growing number of",tr:"giderek artan sayıda"}]},
"like":{a:[{tr:"e. gibi",ex:"Social scientists compare online communities to physical neighborhoods, noting that people often behave like neighbors.",exTr:"Sosyal bilimciler, çevrimiçi toplulukları fiziksel mahallelere benzetir ve insanların genellikle komşular gibi davrandığını belirtir.",yz:4},{tr:"f. hoşlanmak, sevmek, beğenmek",ex:"Most residents like the new bike lanes because they make commuting safer and faster.",exTr:"Çoğu sakin, işe gidip gelmeyi daha güvenli ve hızlı hale getirdiği için yeni bisiklet yollarını beğeniyor.",yz:2}],kl:[{en:"look like",tr:"-e benzemek"},{en:"feel like",tr:"canı istemek"},{en:"and the like",tr:"ve benzerleri"}]},
"first":{a:[{tr:"s. ilk, birinci",ex:"The first vaccine trial produced encouraging results among young, healthy volunteers.",exTr:"İlk aşı denemesi, genç ve sağlıklı gönüllüler arasında umut verici sonuçlar üretti.",yz:4},{tr:"z. önce, ilk olarak",ex:"The clinic administered the vaccine to healthcare workers first before extending it to the public.",exTr:"Klinik, aşıyı halka sunmadan önce ilk olarak sağlık çalışanlarına uyguladı.",yz:3}],kl:[{en:"at first",tr:"ilk başta"},{en:"first of all",tr:"her şeyden önce"},{en:"in the first place",tr:"en başta, zaten"}]},
"year":{a:[{tr:"i. yıl, sene",ex:"The number of international students enrolling in the program has grown steadily every year.",exTr:"Programa kayıt yaptıran uluslararası öğrenci sayısı her yıl istikrarlı biçimde artıyor."}],kl:[{en:"year after year",tr:"yıllar yılı, her yıl"},{en:"all year round",tr:"yıl boyunca"},{en:"in recent years",tr:"son yıllarda"}]},
"new":{a:[{tr:"s. yeni",ex:"The laboratory recently developed a new method for detecting contaminants in drinking water supplies.",exTr:"Laboratuvar, içme suyu kaynaklarındaki kirleticileri tespit etmek için yakın zamanda yeni bir yöntem geliştirdi."}],kl:[{en:"brand new",tr:"yepyeni"},{en:"be new to",tr:"-e yabancı olmak, yeni olmak"},{en:"a new lease of life",tr:"yeni bir hayat, taze soluk"}]},
"become":{a:[{tr:"f. -leşmek, olmak, haline gelmek",ex:"Urban farming has become an increasingly popular solution to food shortages in crowded cities.",exTr:"Kentsel tarım, kalabalık şehirlerdeki gıda kıtlığına giderek daha popüler bir çözüm haline geldi."}],kl:[{en:"become aware of",tr:"-in farkına varmak"},{en:"become accustomed to",tr:"-e alışmak"},{en:"become extinct",tr:"soyu tükenmek"}]},
"life":{a:[{tr:"i. yaşam, hayat",ex:"Marine biologists estimate that ocean acidification could threaten a wide range of aquatic life.",exTr:"Deniz biyologları, okyanus asitlenmesinin geniş bir su canlısı yelpazesini tehdit edebileceğini tahmin ediyor."}],kl:[{en:"way of life",tr:"yaşam biçimi"},{en:"quality of life",tr:"yaşam kalitesi"},{en:"life expectancy",tr:"yaşam beklentisi, ortalama ömür"}]},
"study":{a:[{tr:"i. çalışma, inceleme",ex:"A recent study revealed that air pollution significantly affects children's cognitive development in urban areas.",exTr:"Yakın tarihli bir çalışma, hava kirliliğinin kentsel alanlardaki çocukların bilişsel gelişimini önemli ölçüde etkilediğini ortaya koydu.",yz:4},{tr:"f. incelemek, öğrenim görmek",ex:"Anyone who wishes to study medicine in Germany must first demonstrate an advanced command of the German language.",exTr:"Almanya'da tıp öğrenimi görmek isteyen herkesin önce ileri düzeyde Almanca bildiğini kanıtlaması gerekir.",yz:3}],kl:[{en:"a case study",tr:"vaka çalışması"},{en:"carry out a study",tr:"çalışma yürütmek"},{en:"study abroad",tr:"yurt dışında okumak"}]},
"find":{a:[{tr:"i. buluntu, keşif",ex:"Archaeologists announced that they had made a remarkable find beneath the ruins of the ancient city.",exTr:"Arkeologlar, antik kentin kalıntılarının altında dikkat çekici bir keşif yaptıklarını açıkladı.",yz:4},{tr:"f. bulmak",ex:"Marine biologists hope to find new evidence of coral resilience in the deeper reef systems.",exTr:"Deniz biyologları, daha derin resif sistemlerinde mercan dayanıklılığına dair yeni kanıtlar bulmayı umuyor.",yz:2}],kl:[{en:"find out",tr:"öğrenmek, ortaya çıkarmak"},{en:"find fault with",tr:"-de kusur bulmak"},{en:"be found in",tr:"-de bulunmak"}]},
"just":{a:[{tr:"z. sadece, yalnızca",ex:"The treatment remains effective for just a few hours after each dose.",exTr:"Tedavi her dozdan sonra yalnızca birkaç saat etkili kalır.",yz:4},{tr:"z. az önce, daha yeni",ex:"Researchers have just discovered a second chamber beneath the ancient temple.",exTr:"Araştırmacılar antik tapınağın altında ikinci bir odayı daha yeni keşfetti.",yz:4},{tr:"z. tam, tam da; hemen",ex:"The newly discovered document is just what historians needed to test the theory.",exTr:"Yeni keşfedilen belge, tarihçilerin kuramı sınamak için ihtiyaç duyduğu şeyin tam da kendisidir.",yz:3},{tr:"s. adil, hakkaniyetli",ex:"The court ruled that the new environmental regulation was just and consistent with international law.",exTr:"Mahkeme yeni çevre düzenlemesinin adil ve uluslararası hukukla uyumlu olduğuna karar verdi.",yz:1}],kl:[{en:"just as",tr:"tıpkı ... gibi; tam ... iken"},{en:"just in case",tr:"her ihtimale karşı"},{en:"just about",tr:"hemen hemen"}]},
