"field":{a:[{tr:"i. alan, saha",ex:"Her groundbreaking research in the field of genetics earned international recognition within just a few years.",exTr:"Genetik alanındaki çığır açan araştırması, birkaç yıl içinde uluslararası tanınırlık kazandırdı.",yz:4},{tr:"i. tarla, arazi",ex:"Archaeologists spent an entire summer excavating a field believed to contain Roman artifacts.",exTr:"Arkeologlar, Roma dönemine ait eserler barındırdığına inanılan bir araziyi kazmak için tüm bir yaz geçirdi.",yz:2}],kl:[{en:"in the field of sth",tr:"... alanında"},{en:"an expert in the field",tr:"alanında uzman"},{en:"a field study",tr:"saha çalışması"}]},
