"data":{a:[{tr:"i. veri, bilgi",ex:"Satellites continuously collect data on ocean temperatures to help scientists track climate patterns.",exTr:"Uydular, bilim insanlarının iklim örüntülerini izlemesine yardımcı olmak için okyanus sıcaklıkları hakkında sürekli veri toplar."}],kl:[{en:"data on sth",tr:"bir şeye ilişkin veri"},{en:"collect data",tr:"veri toplamak"},{en:"analyse the data",tr:"verileri çözümlemek"}]},
