"end":{a:[{tr:"i. son, uç",ex:"By the end of the decade, most coastal cities plan to switch entirely to renewable energy.",exTr:"On yılın sonunda, çoğu kıyı şehri tamamen yenilenebilir enerjiye geçmeyi planlıyor.",yz:4},{tr:"f. sona erdirmek, bitirmek",ex:"Researchers hope the new treaty will help end illegal deforestation within the decade.",exTr:"Araştırmacılar, yeni anlaşmanın on yıl içinde yasa dışı ormansızlaşmayı sona erdirmeye yardımcı olmasını umuyor.",yz:3}],kl:[{en:"at the end of",tr:"-in sonunda"},{en:"in the end",tr:"sonunda, nihayetinde"},{en:"put an end to",tr:"-e son vermek"}]},
