"usually":{a:[{tr:"z. genellikle, çoğunlukla",ex:"Migratory birds usually return to the same breeding grounds year after year.",exTr:"Göçmen kuşlar, genellikle yıldan yıla aynı üreme alanlarına geri döner."}],kl:[{en:"as is usually the case",tr:"genellikle olduğu gibi"}]},
