"difficult":{a:[{tr:"s. zor, güç; inatçı",ex:"Predicting earthquakes remains extremely difficult despite decades of intensive geological research.",exTr:"Onlarca yıllık yoğun jeolojik araştırmaya rağmen depremleri öngörmek son derece zor olmayı sürdürüyor."}],kl:[{en:"find it difficult to",tr:"-mekte zorlanmak"},{en:"difficult to understand",tr:"anlaşılması zor"},{en:"a difficult decision",tr:"zor bir karar"}]},
