"carry":{a:[{tr:"f. taşımak",ex:"Migrating birds can carry pollen and seeds across vast distances between continents.",exTr:"Göç eden kuşlar, kıtalar arasındaki geniş mesafeler boyunca polen ve tohum taşıyabilir."}],kl:[{en:"carry out a study",tr:"bir çalışma yürütmek"},{en:"carry on doing sth",tr:"bir şeyi yapmaya devam etmek"},{en:"carry the risk of sth",tr:"bir şeyin riskini taşımak"}]},
"ever":{a:[{tr:"z. hiç, hiçbir zaman",ex:"Few discoveries have ever transformed medicine as profoundly as the invention of antibiotics.",exTr:"Şimdiye dek çok az keşif, antibiyotiklerin icadı kadar tıbbı derinden dönüştürmüştür.",yz:4},{tr:"z. her zaman",ex:"The company's commitment to quality remains, as ever, unwavering.",exTr:"Şirketin kaliteye bağlılığı, her zaman olduğu gibi, sarsılmaz kalmaya devam ediyor.",yz:1}],kl:[{en:"ever since",tr:"o zamandan beri"},{en:"hardly ever",tr:"neredeyse hiç"},{en:"more than ever",tr:"her zamankinden daha fazla"}]},
