"seek":{a:[{tr:"f. aramak",ex:"Patients experiencing chest pain should seek immediate medical attention rather than waiting until morning.",exTr:"Göğüs ağrısı yaşayan hastalar, sabaha kadar beklemek yerine derhal tıbbi yardım aramalıdır.",yz:4},{tr:"f. talep etmek, çabalamak",ex:"The young diplomat sought to resolve the border dispute through peaceful negotiation rather than force.",exTr:"Genç diplomat, sınır anlaşmazlığını güç kullanmak yerine barışçıl müzakereyle çözmeye çabaladı.",yz:3}],kl:[{en:"seek to do sth",tr:"bir şeyi yapmaya çalışmak"},{en:"seek advice from sb",tr:"birinden tavsiye istemek"},{en:"seek refuge",tr:"sığınmak, sığınak aramak"}]},
"task":{a:[{tr:"i. görev, iş",ex:"Completing the annual safety report is a routine task assigned to the maintenance supervisor each December.",exTr:"Yıllık güvenlik raporunu tamamlamak, her Aralık ayında bakım sorumlusuna verilen rutin bir görevdir.",yz:4},{tr:"f. görevlendirmek",ex:"Committee members were tasked with reviewing the university's admission policies before the new semester began.",exTr:"Komite üyeleri, yeni dönem başlamadan önce üniversitenin kabul politikalarını gözden geçirmekle görevlendirildi.",yz:2}],kl:[{en:"carry out a task",tr:"bir görevi yerine getirmek"},{en:"a daunting task",tr:"göz korkutucu bir görev"},{en:"be tasked with sth",tr:"bir şeyle görevlendirilmek"}]},
