"using":{a:[{tr:"f. kullanmak; kullanarak, kullanan (use fiilinin -ing biçimi)",ex:"Researchers confirmed the result using two independent methods.",exTr:"Araştırmacılar sonucu iki bağımsız yöntem kullanarak doğruladı.",yz:4}],kl:[{en:"by using sth",tr:"bir şeyi kullanarak"},{en:"using data from sth",tr:"bir şeyden alınan verileri kullanarak"}]},
"be to do":{a:[{tr:"resmî plan, talimat veya kararlaştırılmış geleceği bildirmek: yapacak olmak/yapması gerekmek",ex:"The two delegations are to meet again after the technical committee publishes its findings.",exTr:"İki heyet, teknik komite bulgularını yayımladıktan sonra yeniden görüşecektir.",yz:4},{tr:"kaçınılmaz veya sonradan gerçekleşecek olayı anlatmak: yapacaktı",ex:"The modest experiment was to influence public health policy for decades.",exTr:"Bu mütevazı deney, halk sağlığı politikasını onlarca yıl etkileyecekti.",yz:3}]},
"gain":{a:[{tr:"f. almak, kazanmak (kilo, ağırlık)",ex:"Many patients gain significant weight after starting certain long-term hormone therapies.",exTr:"Birçok hasta, belirli uzun süreli hormon tedavilerine başladıktan sonra ciddi kilo alır.",yz:3},{tr:"i. kazanç, artış",ex:"The company reported a substantial gain in quarterly profits after cutting production costs.",exTr:"Şirket, üretim maliyetlerini düşürdükten sonra üç aylık kârında önemli bir artış bildirdi.",yz:3}],kl:[{en:"gain access to sth",tr:"bir şeye erişim elde etmek"},{en:"gain insight into sth",tr:"bir şeye ilişkin kavrayış kazanmak"},{en:"gain weight",tr:"kilo almak"}]},
"prove":{a:[{tr:"f. kanıtlamak, ispatlamak",ex:"The new antibiotic proved effective against several drug-resistant bacterial strains during clinical trials.",exTr:"Yeni antibiyotik, klinik deneyler sırasında çeşitli ilaca dirençli bakteri suşlarına karşı etkili olduğunu kanıtladı.",yz:4},{tr:"f. (olduğu) ortaya çıkmak",ex:"The initial diagnosis eventually proved to be incorrect after further laboratory tests were carried out.",exTr:"İlk teşhis, daha ileri laboratuvar testleri yapıldıktan sonra sonunda yanlış olduğu ortaya çıktı.",yz:3}],kl:[{en:"prove to be sth",tr:"... olduğu ortaya çıkmak"},{en:"prove difficult",tr:"zor olduğu anlaşılmak"},{en:"prove sb wrong",tr:"birinin haksız olduğunu kanıtlamak"}]},
"view":{a:[{tr:"f. görmek, saymak, değerlendirmek",ex:"Many economists view rising automation as both a threat and an opportunity for labor markets.",exTr:"Birçok ekonomist, artan otomasyonu işgücü piyasaları için hem bir tehdit hem de bir fırsat olarak görüyor.",yz:4},{tr:"i. manzara",ex:"From the summit, hikers were rewarded with a breathtaking view of the entire valley below.",exTr:"Zirveden, dağcılar aşağıdaki tüm vadinin nefes kesici bir manzarasıyla ödüllendirildi.",yz:2}],kl:[{en:"view sth as",tr:"bir şeyi ... olarak görmek"},{en:"in view of sth",tr:"bir şey göz önüne alındığında"},{en:"with a view to doing sth",tr:"bir şeyi yapmak amacıyla"}]},
"across":{a:[{tr:"z./e. boyunca, çaprazlamasına",ex:"The signal traveled across the entire network within milliseconds, alerting every connected device.",exTr:"Sinyal, milisaniyeler içinde tüm ağ boyunca yayılarak bağlı her cihazı uyardı."}],kl:[{en:"across the country",tr:"ülke genelinde"},{en:"come across sth",tr:"bir şeye rastlamak"},{en:"across the board",tr:"her kesimde, genel olarak"}]},
"city":{a:[{tr:"i. şehir, kent",ex:"Rapid industrialization transformed the small coastal town into a bustling city within two generations.",exTr:"Hızlı sanayileşme, küçük kıyı kasabasını iki nesil içinde hareketli bir şehre dönüştürdü."}],kl:[{en:"the city centre",tr:"şehir merkezi"},{en:"a capital city",tr:"başkent"},{en:"city life",tr:"şehir hayatı"}]},
"low":{a:[{tr:"s. alçak, düşük",ex:"Doctors recommend a low sodium diet for patients diagnosed with high blood pressure.",exTr:"Doktorlar, yüksek tansiyon teşhisi konan hastalara düşük sodyumlu bir diyet öneriyor.",yz:4},{tr:"i. düşük seviye",ex:"Shares of the airline fell to a new low after fuel prices surged unexpectedly.",exTr:"Havayolu şirketinin hisseleri, yakıt fiyatlarının beklenmedik biçimde yükselmesinin ardından yeni bir düşük seviyeye geriledi.",yz:2}],kl:[{en:"low in fat",tr:"düşük yağlı"},{en:"at a low cost",tr:"düşük maliyetle"},{en:"at an all-time low",tr:"tüm zamanların en düşük düzeyinde"}]},
"main":{a:[{tr:"s. ana, başlıca",ex:"Rising temperatures are considered the main driver behind the glacier's rapid retreat.",exTr:"Yükselen sıcaklıklar, buzulun hızlı gerilemesinin başlıca nedeni olarak kabul ediliyor.",yz:4},{tr:"i. ana hat, temel unsur",ex:"Workers shut off the water main before repairing the broken pipe beneath the street.",exTr:"İşçiler, caddenin altındaki kırık boruyu onarmadan önce ana hattı kapattı.",yz:1}],kl:[{en:"the main reason for sth",tr:"bir şeyin başlıca nedeni"},{en:"the main cause of sth",tr:"bir şeyin ana nedeni"},{en:"the main source of income",tr:"başlıca gelir kaynağı"}]},
"specific":{a:[{tr:"s. belirli, özgül",ex:"The study focused on one specific gene linked to an increased risk of heart disease.",exTr:"Çalışma, kalp hastalığı riskinin artmasıyla bağlantılı belirli bir gene odaklandı.",yz:4},{tr:"i. (specifics) ayrıntılar",ex:"The manager avoided discussing specifics, offering only a vague outline of the new marketing plan.",exTr:"Müdür, ayrıntılardan kaçınarak yeni pazarlama planına dair yalnızca belirsiz bir taslak sundu.",yz:2}],kl:[{en:"be specific to sth",tr:"bir şeye özgü olmak"},{en:"a specific example",tr:"belirli bir örnek"},{en:"specific needs",tr:"özel ihtiyaçlar"}]},
