"link":{a:[{tr:"i. bağlantı, bağ",ex:"Scientists established a strong link between air pollution and childhood asthma rates.",exTr:"Bilim insanları, hava kirliliği ile çocukluk çağı astım oranları arasında güçlü bir bağlantı ortaya koydu.",yz:4},{tr:"f. bağlamak, ilişkilendirmek",ex:"Researchers linked the outbreak to contaminated water supplies in three neighboring villages.",exTr:"Araştırmacılar, salgını üç komşu köydeki kirlenmiş su kaynaklarına bağladı.",yz:4}],kl:[{en:"be linked to sth",tr:"bir şeyle bağlantılı olmak"},{en:"a link between two things",tr:"iki şey arasındaki bağlantı"},{en:"a close link",tr:"yakın bağ"}]},
"quite":{a:[{tr:"z. oldukça",ex:"The results were quite different from what the researchers had originally predicted.",exTr:"Sonuçlar, araştırmacıların başlangıçta öngördüğünden oldukça farklıydı.",yz:4},{tr:"z. tamamen",ex:"The two proposals were quite opposite in their approach to funding public transportation.",exTr:"İki öneri, toplu taşımayı finanse etme yaklaşımları bakımından tamamen zıttı.",yz:2}],kl:[{en:"quite a few",tr:"epeyce, hayli"},{en:"not quite",tr:"tam olarak değil"},{en:"quite the opposite",tr:"tam tersi"}]},
