"along":{a:[{tr:"z./e. boyunca, ileriye doğru",ex:"Researchers walked along the riverbank, collecting water samples every few hundred meters.",exTr:"Araştırmacılar, her birkaç yüz metrede bir su örneği toplayarak nehir kıyısı boyunca yürüdü."}],kl:[{en:"along with sth",tr:"bir şeyle birlikte"},{en:"along the coast",tr:"kıyı boyunca"},{en:"get along with sb",tr:"biriyle iyi geçinmek"}]},
"clearly":{a:[{tr:"z. açıkça, kuşkusuz",ex:"The satellite images clearly show the extent of deforestation across the Amazon basin over the past decade.",exTr:"Uydu görüntüleri, son on yılda Amazon havzasındaki ormansızlaşmanın boyutunu açıkça göstermektedir."}],kl:[{en:"clearly defined",tr:"açıkça tanımlanmış"},{en:"clearly show that",tr:"açıkça ... olduğunu göstermek"}]},
"cultural":{a:[{tr:"s. kültürel",ex:"Museums play a vital role in preserving the cultural heritage of indigenous communities around the world.",exTr:"Müzeler, dünya genelindeki yerli toplulukların kültürel mirasını korumada hayati bir rol oynar."}],kl:[{en:"cultural heritage",tr:"kültürel miras"},{en:"cultural differences",tr:"kültürel farklılıklar"},{en:"cultural diversity",tr:"kültürel çeşitlilik"}]},
"expand":{a:[{tr:"f. genişlemek, büyümek; genişletmek",ex:"The university plans to expand its research facilities to accommodate a growing number of graduate students.",exTr:"Üniversite, artan sayıda lisansüstü öğrenciyi barındırmak için araştırma tesislerini genişletmeyi planlıyor."}],kl:[{en:"expand into new markets",tr:"yeni pazarlara açılmak"},{en:"expand rapidly",tr:"hızla büyümek"},{en:"expand on sth",tr:"bir şeyi ayrıntılandırmak"}]},
"describe":{a:[{tr:"f. tanımlamak, betimlemek, tarif etmek",ex:"Early explorers described the island's wildlife in remarkably accurate detail despite limited equipment.",exTr:"İlk kâşifler, sınırlı ekipmana rağmen adanın yaban hayatını dikkat çekici bir doğrulukla betimledi."}],kl:[{en:"describe sth as",tr:"bir şeyi ... olarak nitelemek"},{en:"be described as",tr:"... olarak tanımlanmak"},{en:"describe sth in detail",tr:"bir şeyi ayrıntılı anlatmak"}]},
"past":{a:[{tr:"i. geçmiş",ex:"Archaeological findings offer valuable clues about how ancient civilizations survived in the distant past.",exTr:"Arkeolojik bulgular, antik uygarlıkların çok eski geçmişte nasıl hayatta kaldığına dair değerli ipuçları sunar.",yz:4},{tr:"e. -in yanından (geçerek)",ex:"The delivery driver walked past the locked gate without noticing the small side entrance.",exTr:"Kurye, küçük yan girişi fark etmeden kilitli kapının yanından geçti.",yz:2}],kl:[{en:"in the past",tr:"geçmişte"},{en:"over the past decade",tr:"son on yılda"},{en:"walk past sb",tr:"birinin yanından yürüyerek geçmek"}]},
"together":{a:[{tr:"z. birlikte, beraber",ex:"Scientists from twelve countries worked together to map the ocean floor in unprecedented detail.",exTr:"On iki ülkeden bilim insanları, okyanus tabanını benzeri görülmemiş bir ayrıntıyla haritalamak için birlikte çalıştı.",yz:4},{tr:"s. düzenli, toparlanmış",ex:"Despite the chaos backstage, the young director remained remarkably together throughout the entire show.",exTr:"Sahne arkasındaki kargaşaya rağmen, genç yönetmen gösteri boyunca dikkat çekici derecede toparlanmış kaldı.",yz:1}],kl:[{en:"together with sth",tr:"bir şeyle birlikte"},{en:"work together",tr:"birlikte çalışmak"},{en:"bring people together",tr:"insanları bir araya getirmek"}]},
