"fail":{a:[{tr:"f. başarısız olmak; -ememek; (makine, organ) iflas etmek, arızalanmak",ex:"Older water pipes frequently fail during periods of extreme temperature fluctuation.",exTr:"Eski su boruları, aşırı sıcaklık dalgalanmaları dönemlerinde sıklıkla arızalanır."}],kl:[{en:"fail to do sth",tr:"bir şeyi yapamamak, yapmamak"},{en:"fail an exam",tr:"sınavda kalmak"},{en:"without fail",tr:"mutlaka, aksatmadan"}]},
