"based":{a:[{tr:"f. dayandırdı, temellendirdi (base fiilinin geçmiş/V3 biçimi)",ex:"The researchers based their conclusions on long-term observations.",exTr:"Araştırmacılar sonuçlarını uzun süreli gözlemlere dayandırdı.",yz:4},{tr:"s. dayanan, -e dayalı",ex:"The clinic's treatment plan is based on the latest evidence from peer-reviewed medical journals.",exTr:"Kliniğin tedavi planı, hakemli tıp dergilerindeki en güncel kanıtlara dayanmaktadır.",yz:3}],kl:[{en:"based on sth",tr:"bir şeye dayalı, dayanarak"},{en:"based on the assumption that",tr:"... varsayımına dayanarak"},{en:"evidence-based medicine",tr:"kanıta dayalı tıp"}]},
