"job":{a:[{tr:"i. iş, meslek",ex:"Automation is expected to eliminate certain jobs while creating entirely new categories of employment.",exTr:"Otomasyonun bazı işleri ortadan kaldırırken tümüyle yeni istihdam alanları yaratması bekleniyor.",yz:4},{tr:"i. görev, vazife",ex:"It is the school's job to ensure that every child feels safe and included.",exTr:"Her çocuğun kendini güvende ve dahil hissetmesini sağlamak okulun görevidir.",yz:2}],kl:[{en:"do a good job",tr:"işi iyi yapmak"},{en:"lose one's job",tr:"işini kaybetmek"},{en:"job satisfaction",tr:"iş tatmini"}]},
