"industry":{a:[{tr:"i. endüstri, sanayi",ex:"The fishing industry has struggled to adapt to stricter environmental regulations in recent years.",exTr:"Balıkçılık sektörü, son yıllarda daha sıkı çevre düzenlemelerine uyum sağlamakta zorlandı.",yz:4},{tr:"i. çalışkanlık",ex:"The young apprentice impressed his supervisor with his industry and attention to detail.",exTr:"Genç çırak, çalışkanlığı ve ayrıntıya verdiği önemle amirini etkiledi.",yz:1}],kl:[{en:"the tourism industry",tr:"turizm sektörü"},{en:"heavy industry",tr:"ağır sanayi"},{en:"the manufacturing industry",tr:"imalat sanayisi"}]},
