"economy":{a:[{tr:"i. ekonomi",ex:"Tourism plays a crucial role in the economy of many small island nations.",exTr:"Turizm, birçok küçük ada ülkesinin ekonomisinde çok önemli bir rol oynar.",yz:4},{tr:"i. tutum, tasarruf",ex:"Turning off unused lights is a small economy that can noticeably lower a household's monthly electricity bill.",exTr:"Kullanılmayan ışıkları kapatmak, bir hanenin aylık elektrik faturasını gözle görülür biçimde azaltabilecek küçük bir tasarruftur.",yz:2}],kl:[{en:"the global economy",tr:"küresel ekonomi"},{en:"boost the economy",tr:"ekonomiyi canlandırmak"},{en:"economy of scale",tr:"ölçek ekonomisi"}]},
